-- Review on a development branch before production.
create table public.work_sessions (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),user_id uuid not null,person_id uuid not null references public.people(id),work_date date not null default current_date,started_at timestamptz not null default now(),ended_at timestamptz,last_heartbeat_at timestamptz not null default now(),active_seconds integer not null default 0,idle_seconds integer not null default 0,break_seconds integer not null default 0,status text not null default 'working' check(status in ('working','break','idle','completed','auto_closed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.work_breaks (id uuid primary key default gen_random_uuid(),work_session_id uuid not null references public.work_sessions(id) on delete cascade,started_at timestamptz not null default now(),ended_at timestamptz,duration_seconds integer not null default 0);
create table public.attendance_adjustments (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),work_session_id uuid not null references public.work_sessions(id),requested_by uuid not null,original_started_at timestamptz,original_ended_at timestamptz,requested_started_at timestamptz,requested_ended_at timestamptz,reason text not null,status text not null default 'pending' check(status in ('pending','approved','rejected')),reviewer_user_id uuid,reviewed_at timestamptz,created_at timestamptz not null default now());
create unique index one_active_work_session_per_user on public.work_sessions(organization_id,user_id) where ended_at is null; create unique index one_open_break_per_session on public.work_breaks(work_session_id) where ended_at is null; create index work_sessions_org_date on public.work_sessions(organization_id,work_date);
alter table public.work_sessions enable row level security; alter table public.work_breaks enable row level security; alter table public.attendance_adjustments enable row level security;
create policy session_self_or_lead on public.work_sessions for select to authenticated using(user_id=auth.uid() or private.has_org_role(organization_id,array['ceo','admin','manager','team_lead']));
create policy break_session_visible on public.work_breaks for select to authenticated using(exists(select 1 from public.work_sessions s where s.id=work_session_id and (s.user_id=auth.uid() or private.has_org_role(s.organization_id,array['ceo','admin','manager','team_lead']))));
create policy adjustment_visible on public.attendance_adjustments for select to authenticated using(requested_by=auth.uid() or private.has_org_role(organization_id,array['ceo','admin','manager','team_lead'])); grant select on public.work_sessions,public.work_breaks,public.attendance_adjustments to authenticated;
create or replace function public.attendance_action(p_action text,p_session uuid default null,p_reason text default null,p_approve boolean default null) returns jsonb language plpgsql security definer set search_path=public,auth,pg_temp as $$ declare u uuid:=auth.uid(); s public.work_sessions; o uuid; r text; p uuid; n timestamptz:=now(); begin if u is null then raise exception 'unauthenticated'; end if; select organization_id,role into o,r from public.organization_members where user_id=u and active order by joined_at limit 1; if o is null then raise exception 'no active membership'; end if; if p_action in ('start','break','resume','heartbeat','end') and r not in ('manager','team_lead','employee','viewer') then raise exception 'attendance_exempt'; end if; select id into p from public.people where organization_id=o and auth_user_id=u limit 1; if p_action='start' then select * into s from public.work_sessions where organization_id=o and user_id=u and ended_at is null; if s.id is null then insert into public.work_sessions(organization_id,user_id,person_id,work_date) values(o,u,p,n::date) returning * into s; end if; return to_jsonb(s); end if; select * into s from public.work_sessions where id=coalesce(p_session,(select id from public.work_sessions where organization_id=o and user_id=u and ended_at is null limit 1)) and organization_id=o; if s.id is null then raise exception 'session_not_found'; end if; if s.user_id<>u then raise exception 'forbidden'; end if; if p_action='break' and s.status='working' then insert into public.work_breaks(work_session_id) values(s.id) on conflict do nothing; update public.work_sessions set status='break',last_heartbeat_at=n,updated_at=n where id=s.id returning * into s; elsif p_action='resume' and s.status='break' then update public.work_breaks set ended_at=n,duration_seconds=extract(epoch from n-started_at)::int where work_session_id=s.id and ended_at is null; update public.work_sessions set status='working',last_heartbeat_at=n,updated_at=n where id=s.id returning * into s; elsif p_action='heartbeat' and s.ended_at is null then update public.work_sessions set active_seconds=active_seconds+greatest(0,least(120,extract(epoch from n-last_heartbeat_at)::int)),last_heartbeat_at=n,updated_at=n where id=s.id and status='working' returning * into s; elsif p_action='end' and s.ended_at is null then update public.work_breaks set ended_at=n,duration_seconds=extract(epoch from n-started_at)::int where work_session_id=s.id and ended_at is null; update public.work_sessions set ended_at=n,status='completed',last_heartbeat_at=n,updated_at=n where id=s.id returning * into s; end if; return to_jsonb(s); end $$;
create or replace function public.start_work_session() returns jsonb language sql security definer set search_path=public,auth,pg_temp as $$select public.attendance_action('start')$$; create or replace function public.start_work_break() returns jsonb language sql security definer set search_path=public,auth,pg_temp as $$select public.attendance_action('break')$$; create or replace function public.resume_work_session() returns jsonb language sql security definer set search_path=public,auth,pg_temp as $$select public.attendance_action('resume')$$; create or replace function public.heartbeat_work_session() returns jsonb language sql security definer set search_path=public,auth,pg_temp as $$select public.attendance_action('heartbeat')$$; create or replace function public.end_work_session() returns jsonb language sql security definer set search_path=public,auth,pg_temp as $$select public.attendance_action('end')$$;
revoke all on function public.attendance_action(text,uuid,text,boolean),public.start_work_session(),public.start_work_break(),public.resume_work_session(),public.heartbeat_work_session(),public.end_work_session() from public; grant execute on function public.start_work_session(),public.start_work_break(),public.resume_work_session(),public.heartbeat_work_session(),public.end_work_session() to authenticated;
